/*
 * A118588  Triangle generated by e.g.f.: A(x,y) = exp(x + y*(x^2+x^3)), read
 *          by rows of length [n/2+1].
 * https://oeis.org/A118588
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, tabl
 * Formula:   The egf of A118588 is A(x,y)=exp(x+y(x²+x³)). The coefficient of
 *            xⁿyᵏ in A is (1/k!) · Σ_{a=0}^k binom(k,a) / (n−3k+a)! for n≥2k,
 *            and the actual triangle entry is a(n,k) = n! · (coeff of xⁿyᵏ).
 *            Here a is the row index, k the column (0≤k≤⌊a/2⌋). The ordinary
 *            sequence is obtained by reading the tri...
 * Range:     u8 n <= 13, u16 n <= 22, u32 n <= 45, u64 n <= 45, u128 n <= 45,
 *            big any n
 * Helpers:   factorial
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Note: this implementation uses only the provided utilities
   and standard integer operations; it works for any definition
   of seq_t and idx_t.  It runs in O(k²) time per query
   (k≈row/2, row≈O(√n)), and requires no memoisation. */

#include <stdint.h>
#include "../utils/factorial.h"

seq_t a(idx_t n)
{
    /* Find the row r and the column k that contain the n‑th flatten
       element.  The cumulative length up to a row r is
       S(r) = Σ_{i=0}^r (⌊i/2⌋+1).  Scan incrementally (r will be small). */
    idx_t sum = 0;          /* #elements before current row */
    idx_t r   = 0;          /* current row index */
    while (1) {
        idx_t len = r / 2 + 1;          /* length of row r */
        if (sum + len > n) break;       /* n lies in this row */
        sum += len;
        ++r;
    }
    idx_t k = n - sum;          /* column index in row r */

    /* Row 0 or column 0 always has value 1. */
    if (k == 0) return (seq_t)1;

    /* Pre‑compute k! once. */
    seq_t kfact = factorial(k);

    /* The summation index a runs from max(0, 3k‑n) to k. */
    idx_t a_min = (3 * k > r) ? (3 * k - r) : (idx_t)0;

    seq_t sum_term = 0;               /* running sum of all terms */
    seq_t binom = 1;                   /* binomial(k,0) = 1 */

    for (idx_t a = 0; a <= k; ++a) {
        /* Update binomial coefficient for the next a. */
        if (a > 0)
            binom = binom * (k - a + 1) / a;

        if (a < a_min) continue;      /* term would be zero (negative denom) */

        /* Compute the factorial quotient n! / (n−3k+a)! as a product. */
        idx_t denom = r - 3 * k + a;   /* n−3k+a */
        seq_t prod = 1;
        for (idx_t t = denom + 1; t <= r; ++t) {
            prod *= (seq_t)t;
        }

        /* Term: binom * prod / k!  (exact division). */
        seq_t term = prod;
        term *= binom;
        term /= kfact;

        sum_term += term;
    }

    return sum_term;
}
